// A Dark Room 1.4 on the website: the original controller, CSS and sounds, running in the player's
// page. The original scripts are translated in legacy.ts (generated by re/darkroom/tools/build-port.mjs)
// and created per Play, so state and timers never leak between sessions. The original's
// localStorage save becomes one account-scoped server file, JSON like the original's gameState.
import * as jqueryNamespace from 'jquery';
import 'jquery-color';
import scopedCss from './adr.css?raw';
import { translate } from './text.ts';
import { createAdrGame, type AdrGame } from './legacy.ts';
import type { GameContext } from '../../../src/sdk/index.ts';

const jQuery = ((jqueryNamespace as unknown as { default?: JQueryStatic }).default
  ?? jqueryNamespace) as unknown as JQueryStatic;

const audioUrls = import.meta.glob('../assets/audio/*.flac', {
  query: '?url', import: 'default', eager: true,
}) as Record<string, string>;

const SAVE_NAME = 'savegame.json';
const SAVE_DELAY = 400;

function resolveAudio(path: string): string {
  const name = path.replace(/^.*\//, '');
  return audioUrls[`../assets/audio/${name}`] ?? path;
}

/** A jQuery bound to the game's own DOM, so the original's global selectors cannot reach the site. */
function scopedJQuery(root: HTMLElement): JQueryStatic {
  const $ = ((selector: unknown, context?: unknown) => {
    if (typeof selector === 'string' && !selector.trimStart().startsWith('<')) {
      const s = selector.trim();
      if (s === 'body' || s === 'head') return jQuery(root);
      if (s === 'document') return jQuery(document);
      if (s === 'window') return jQuery(window);
      return jQuery(selector as string, (context ?? root) as Element);
    }
    return jQuery(selector as never, context as never);
  }) as unknown as JQueryStatic;
  $.extend = jQuery.extend;
  $.each = jQuery.each;
  $.isEmptyObject = jQuery.isEmptyObject;
  $.Callbacks = jQuery.Callbacks;
  return $;
}

class Timers {
  private readonly ids = new Set<number>();

  setTimeout = (cb: (...args: never[]) => void, ms: number): number => {
    const id = window.setTimeout(() => { this.ids.delete(id); cb(); }, ms);
    this.ids.add(id);
    return id;
  };

  setInterval = (cb: (...args: never[]) => void, ms: number): number => {
    const id = window.setInterval(cb, ms);
    this.ids.add(id);
    return id;
  };

  clearTimeout = (id: number): void => {
    this.ids.delete(id);
    window.clearTimeout(id);
  };

  clearInterval = (id: number): void => {
    this.ids.delete(id);
    window.clearInterval(id);
  };

  clearAll(): void {
    for (const id of this.ids) {
      window.clearTimeout(id);
      window.clearInterval(id);
    }
    this.ids.clear();
  }
}

class SaveFile {
  readonly storage: GameContext['storage'];
  private loaded: unknown = null;
  private lastJson = '';
  private pending: string | null = null;
  private timer: number | null = null;
  private writing: Promise<void> = Promise.resolve();

  constructor(storage: GameContext['storage']) {
    this.storage = storage;
  }

  async read(): Promise<void> {
    try {
      const bytes = await Promise.race([
        this.storage.get(SAVE_NAME),
        new Promise<null>((resolve) => setTimeout(() => resolve(null), 2500)),
      ]);
      if (bytes) {
        this.lastJson = new TextDecoder().decode(bytes);
        this.loaded = JSON.parse(this.lastJson) as unknown;
      }
    } catch {
      this.loaded = null;
    }
  }

  save(json: string): void {
    this.lastJson = json;
    this.pending = json;
    if (this.timer != null) return;
    this.timer = window.setTimeout(() => {
      this.timer = null;
      void this.flush();
    }, SAVE_DELAY);
  }

  saveRaw(json: string): void {
    this.lastJson = json;
    try { this.loaded = JSON.parse(json) as unknown; } catch { this.loaded = null; }
    this.pending = json;
    void this.flush();
  }

  load(): unknown | null { return this.loaded; }
  last(): string { return this.lastJson || '{}'; }

  clear(): void {
    this.loaded = null;
    this.lastJson = '';
    this.pending = null;
    if (this.timer != null) { window.clearTimeout(this.timer); this.timer = null; }
    void this.storage.delete(SAVE_NAME).catch(() => {});
  }

  async flush(): Promise<void> {
    const json = this.pending;
    if (json == null) return;
    this.pending = null;
    this.writing = this.writing.then(async () => {
      try {
        await this.storage.put(SAVE_NAME, new TextEncoder().encode(json));
      } catch {
        // a save that cannot be written is retried on the next state change
      }
    });
    await this.writing;
  }
}

function stopAudio(game: AdrGame | null): void {
  if (!game) return;
  const audio = game.AudioEngine;
  try {
    audio._currentBackgroundMusic?.source?.stop();
    audio._currentEventAudio?.source?.stop();
    audio._currentSoundEffectAudio?.source?.stop();
    audio._master?.disconnect();
  } catch {
    // already stopped
  }
  audio._initialized = false;
}

const SKELETON = `
<div id="wrapper">
  <div id="saveNotify">saved.</div>
  <div id="content">
    <div id="outerSlider">
      <div id="main">
        <div id="header"></div>
      </div>
    </div>
  </div>
</div>`;

const EXTRA_CSS = `
.adr-root, .adr-root * { box-sizing: content-box; }
.adr-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #fff;
  color: #000;
  transform: translateZ(0);
  outline: none;
  user-select: none;
}
.adr-root div#wrapper {
  position: absolute;
  left: 50%;
  top: 0;
  margin: 0;
  transform-origin: top center;
}
.adr-root #content { height: 700px; }
.adr-root textarea { user-select: text; }
.adr-root #saveNotify { position: absolute; }
.adr-root .menu { position: absolute; right: 12px; bottom: 10px; }
`;

export class DarkRoomGame {
  private readonly host: HTMLElement;
  private readonly ctx: GameContext;
  private root!: HTMLDivElement;
  private style!: HTMLStyleElement;
  private game: AdrGame | null = null;
  private save: SaveFile | null = null;
  private timers = new Timers();
  private keyDown: ((e: KeyboardEvent) => void) | null = null;
  private keyUp: ((e: KeyboardEvent) => void) | null = null;
  private audioResume: (() => void) | null = null;
  private resize: ResizeObserver | null = null;
  private stopped = false;

  constructor(host: HTMLElement, ctx: GameContext) {
    this.host = host;
    this.ctx = ctx;
  }

  async start(): Promise<void> {
    this.root = document.createElement('div');
    this.root.className = 'adr-root game-root';
    this.root.tabIndex = 0;
    this.style = document.createElement('style');
    this.style.textContent = scopedCss + EXTRA_CSS;
    this.host.replaceChildren(this.root);
    this.save = new SaveFile(this.ctx.storage);
    await this.save.read();
    this.bindSession();
    this.run();
    this.root.focus();
  }

  private bindSession(): void {
    const signal = this.ctx.signal;
    window.addEventListener('keydown', (e) => {
      if (!this.keyDown) return;
      const target = e.target as HTMLElement | null;
      if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return;
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) e.preventDefault();
      this.keyDown(e);
    }, { signal });
    window.addEventListener('keyup', (e) => { this.keyUp?.(e); }, { signal });
    document.addEventListener('click', () => { this.audioResume?.(); }, { signal });
    this.resize = new ResizeObserver(() => this.scale());
    this.resize.observe(this.host);
  }

  private run(): void {
    this.timers = new Timers();
    const $ = scopedJQuery(this.root);
    this.root.replaceChildren(this.style);
    this.root.insertAdjacentHTML('beforeend', SKELETON);
    this.game = createAdrGame({
      $, jQuery: jQuery as never, _: translate,
      document, window,
      root: jQuery(this.root),
      Base64: {
        encode: (text) => btoa(unescape(encodeURIComponent(text))),
        decode: (text) => decodeURIComponent(escape(atob(text))),
      },
      persistence: {
        save: (json) => this.save?.save(json),
        saveRaw: (json) => this.save?.saveRaw(json),
        load: () => this.save?.load() ?? null,
        last: () => this.save?.last() ?? '{}',
        clear: () => this.save?.clear(),
      },
      resolveAudio,
      audioContext: this.ctx.audio,
      restart: () => this.restart(),
      bindKeys: (down, up) => { this.keyDown = down as never; this.keyUp = up as never; },
      onAudioResume: (cb) => { this.audioResume = cb; },
      setTimeout: this.timers.setTimeout,
      setInterval: this.timers.setInterval,
      clearTimeout: this.timers.clearTimeout,
      clearInterval: this.timers.clearInterval,
    });
    this.game.Engine.init({});
    this.scale();
  }

  private scale(): void {
    if (!this.root || this.stopped) return;
    const wrapper = this.root.querySelector<HTMLElement>('#wrapper');
    if (!wrapper) return;
    const w = this.host.clientWidth, h = this.host.clientHeight;
    const s = Math.min(w / 920, h / 740, 1.6);
    wrapper.style.transform = `translateX(-50%) scale(${Math.max(0.35, s)})`;
  }

  private restart(): void {
    this.stopGame();
    this.run();
    this.root.focus();
  }

  private stopGame(): void {
    this.keyDown = null;
    this.keyUp = null;
    this.audioResume = null;
    this.timers.clearAll();
    stopAudio(this.game);
    if (this.game) {
      try { jQuery(this.root).stop(true, true); } catch { /* ignore */ }
    }
    this.game = null;
    this.root.replaceChildren();
  }

  async stop(): Promise<void> {
    if (this.stopped) return;
    this.stopped = true;
    this.resize?.disconnect();
    this.resize = null;
    this.stopGame();
    await this.save?.flush();
    this.root.remove();
  }
}

